// Original synthesized SFX + music loop (generated by /app/scripts/synth_audio.py).
import { AudioPlayer, createAudioPlayer, setAudioModeAsync } from "expo-audio";

const SFX = {
  pop: require("../../assets/sounds/pop.wav"),
  swap: require("../../assets/sounds/swap.wav"),
  invalid: require("../../assets/sounds/invalid.wav"),
  combo1: require("../../assets/sounds/combo1.wav"),
  combo2: require("../../assets/sounds/combo2.wav"),
  combo3: require("../../assets/sounds/combo3.wav"),
  combo4: require("../../assets/sounds/combo4.wav"),
  special: require("../../assets/sounds/special.wav"),
  win: require("../../assets/sounds/win.wav"),
  lose: require("../../assets/sounds/lose.wav"),
  restore: require("../../assets/sounds/restore.wav"),
  coin: require("../../assets/sounds/coin.wav"),
  hammer: require("../../assets/sounds/hammer.wav"),
  cheer: require("../../assets/sounds/cheer.wav"),
  tick: require("../../assets/sounds/tick.wav"),
  jackpot: require("../../assets/sounds/jackpot.wav"),
};
const MUSIC = require("../../assets/sounds/music.wav");

export type SfxName = keyof typeof SFX;

const players: Partial<Record<SfxName, AudioPlayer>> = {};
let music: AudioPlayer | null = null;
let sfxOn = true;
let musicOn = true;
let modeSet = false;

function ensureMode() {
  if (modeSet) return;
  modeSet = true;
  setAudioModeAsync({ playsInSilentMode: true, interruptionMode: "mixWithOthers", shouldPlayInBackground: false }).catch(() => {});
}

export function playSfx(name: SfxName) {
  if (!sfxOn) return;
  try {
    ensureMode();
    const p = players[name] ?? (players[name] = createAudioPlayer(SFX[name]));
    p.seekTo(0).catch(() => {});
    p.play();
  } catch {}
}

export const comboSfx = (chain: number): SfxName => (chain <= 0 ? "pop" : (`combo${Math.min(chain, 4)}` as SfxName));

export function startMusic() {
  if (!musicOn) return;
  try {
    ensureMode();
    if (!music) {
      music = createAudioPlayer(MUSIC);
      music.loop = true;
      music.volume = 0.35;
    }
    if (!music.playing) music.play();
  } catch {}
}

export function pauseMusic() {
  try {
    music?.pause();
  } catch {}
}

export function setSfxEnabled(v: boolean) {
  sfxOn = v;
}

export function setMusicEnabled(v: boolean) {
  musicOn = v;
  if (!v) pauseMusic();
}
